#include "Vfursoy_s0_core.h"
#include "verilated.h"
#include <array>
#include <cstdint>
#include <iostream>
#include <stdexcept>
static uint32_t addi(unsigned d,unsigned s,int i){return(uint32_t(i)<<20)|(s<<15)|(d<<7)|0x13;}
static uint32_t csr(unsigned f,unsigned d,unsigned s,unsigned a){return(a<<20)|(s<<15)|(f<<12)|(d<<7)|0x73;}
struct C{uint64_t pc;uint32_t insn;bool write;unsigned rd;uint64_t data;};
int main(int argc,char**argv){Verilated::commandArgs(argc,argv);Vfursoy_s0_core d;constexpr uint64_t B=0x80000000;const std::array<uint32_t,6>p={addi(1,0,0x55),csr(1,2,1,0x340),csr(2,3,0,0x340),csr(5,0,31,0x340),csr(5,4,31,0x300),csr(1,0,0,0xc00)};const std::array<C,5>e={{{B,p[0],1,1,0x55},{B+4,p[1],1,2,0},{B+8,p[2],1,3,0x55},{B+12,p[3],0,0,0},{B+16,p[4],1,4,0x0000000a00001800ULL}}};bool iv=0,fire=0,tr=0;uint32_t id=0;unsigned n=0,cy=0;auto ck=[](bool x,const char*s){if(!x)throw std::runtime_error(s);};try{d.clk_i=0;d.rst_i=1;d.imem_req_ready_i=0;d.imem_rsp_valid_i=0;d.dmem_req_ready_i=0;d.dmem_rsp_valid_i=0;d.dmem_rsp_data_i=0;d.eval();d.clk_i=1;d.eval();++cy;for(;cy<60&&!tr;){d.clk_i=0;d.rst_i=0;d.imem_req_ready_i=1;d.imem_rsp_valid_i=iv;d.imem_rsp_insn_i=id;d.eval();if(d.imem_req_valid_o&&!iv){auto x=(uint64_t(d.imem_req_addr_o)-B)/4;ck(x<p.size(),"imem");id=p[x];iv=1;d.imem_rsp_valid_i=1;d.imem_rsp_insn_i=id;d.eval();}if(d.commit_valid_o){ck(n<e.size(),"count");auto x=e[n++];ck(uint64_t(d.commit_pc_o)==x.pc&&uint32_t(d.commit_insn_o)==x.insn&&bool(d.commit_rd_write_o)==x.write&&unsigned(d.commit_rd_o)==x.rd&&uint64_t(d.commit_rd_data_o)==x.data,"commit");}if(d.trap_valid_o){ck(n==e.size()&&uint64_t(d.trap_pc_o)==B+20&&uint32_t(d.trap_insn_o)==p[5],"trap event");tr=1;}fire=iv&&d.imem_rsp_ready_o;d.clk_i=1;d.eval();++cy;if(fire)iv=0;if(tr){ck(uint64_t(d.csr_mscratch_o)==31&&uint64_t(d.csr_mepc_o)==B+20&&uint64_t(d.csr_mcause_o)==2&&uint64_t(d.csr_mtval_o)==p[5]&&uint64_t(d.csr_mstatus_o)==0x0000000a00001882ULL,"CSR/trap state");}}ck(tr&&n==e.size(),"flow");d.final();std::cout<<"{\"status\":\"pass\",\"cycles\":"<<cy<<",\"commits\":"<<n<<"}\n";return 0;}catch(const std::exception&x){std::cerr<<"CORE_CSR_S0_MISMATCH cycle="<<cy<<" commits="<<n<<" reason="<<x.what()<<'\n';return 1;}}
